import{_ as a,c as n,a as d,o as r}from"./app-BPKKDfYB.js";const i={};function c(l,e){return r(),n("div",null,e[0]||(e[0]=[d('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-08-11-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-08-11-资讯日报"><span>2026-08-11 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="寻明生科获1亿美元融资-迈向生物世界模型" tabindex="-1"><a class="header-anchor" href="#寻明生科获1亿美元融资-迈向生物世界模型"><span>寻明生科获1亿美元融资，迈向生物世界模型</span></a></h3><p>寻明生科获1亿美元B轮融资，累计近2亿。将强化生物基座模型研发，升级实验体系。其闭环基础设施让模型持续进化，已产出高价值抗体，与药企合作，创始人称迈向生物世界模型。<a href="https://mp.weixin.qq.com/s?__biz=MzkwMDI2ODE0OQ==&amp;chksm=c1d288a585e580dcf9f41387611ae0bdaa13e1f8188385c3dafa9f942d60a70977a489aa7d0f&amp;idx=1&amp;mid=2247504143&amp;sn=10419b6dba000ac35a3602c5ca383468#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="黄仁勋-ai算力要成「可投资资产」" tabindex="-1"><a class="header-anchor" href="#黄仁勋-ai算力要成「可投资资产」"><span>黄仁勋：AI算力要成「可投资资产」</span></a></h3><p>黄仁勋：NVIDIA与六家金融机构合作，建独立融资平台，动员超5000亿美元资本支持AI基建，让AI工厂成可投资资产，认为AI时代算力即收入。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85373d6042589603237c47bad2b1ef7438ab67c6818f169b471e095a547cf45d86ba57270247&amp;idx=2&amp;mid=2651049640&amp;sn=dc4142d4a6a74bda646823c0e42c05ff#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="黄仁勋拉金融巨鳄砸5000亿建ai工厂" tabindex="-1"><a class="header-anchor" href="#黄仁勋拉金融巨鳄砸5000亿建ai工厂"><span>黄仁勋拉金融巨鳄砸5000亿建AI工厂</span></a></h3><p>黄仁勋：AI已从研究走向生产，算力即收入。英伟达联合六大金融机构，将调动超5000亿美元建AI工厂，其算力有独特优势，能让工厂成基础设施资产。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3MTkxMjYzOA==&amp;chksm=cfc6585c0dde440f004006815f32b3583ff0082c8b4aeff909786a285565d5ef399c947e0d24&amp;idx=1&amp;mid=2247516823&amp;sn=ce11374af9a3fca773805dc0282404c5#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude全球推行文本隐形水印引争议" tabindex="-1"><a class="header-anchor" href="#claude全球推行文本隐形水印引争议"><span>Claude全球推行文本隐形水印引争议</span></a></h3><p>Anthropic签署欧盟AI法案，Claude新模型将全量嵌入隐形水印、附加签名元数据，全球适用。虽开发检测工具，但机制有局限。此前A社就用Unicode贴暗标，水印是否影响质量遭质疑。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e910b80bac5eb5b62241408ac8d56ad8be77bcd3e2e86b2584fe6778e6186220027a9ca318cc&amp;idx=2&amp;mid=2247911316&amp;sn=36fdf8306585f064f4284f442f1201dd#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="华为天才少年创业做具身大脑" tabindex="-1"><a class="header-anchor" href="#华为天才少年创业做具身大脑"><span>华为天才少年创业做具身大脑</span></a></h3><p>前华为天才少年楼燚航创立引力蓝移，做具身大脑。采用分层架构，认为具身智能Scaling拐点已到。规划模型参数规模，与汇川合作，24个月推进商业化，产品验证是挑战。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=913199c8dcf8c421792e063d8c9f71088fbdfab5266695b389fa37f01d735257d111671e0458&amp;idx=1&amp;mid=2247741424&amp;sn=24d3e51092561949969cca7ce4ae9ead#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="zig创始人批bun-ai重构代码是-烂代码" tabindex="-1"><a class="header-anchor" href="#zig创始人批bun-ai重构代码是-烂代码"><span>Zig创始人批Bun AI重构代码是‘烂代码’</span></a></h3><p>Bun创建者Jarred Sumner用Claude 11天完成Bun从Zig到Rust移植。Zig创始人Andrew Kelley批评其编程不规范，认为代码没审核，AI生成代码缺监督会有无数问题。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc7f16c6be5493422590a49b2f1451a7780a9d18638b51afff25b4d30e40e9ee80c99d792ef6&amp;idx=3&amp;mid=2651290628&amp;sn=b803432db5d8af7fda584c972afe4941#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="daphne-koller-ai制药缺1000倍数据" tabindex="-1"><a class="header-anchor" href="#daphne-koller-ai制药缺1000倍数据"><span>Daphne Koller：AI制药缺1000倍数据</span></a></h3><p>机器学习先驱 Daphne Koller 警告：AI 制药虽能提升分子设计效率，但新药研发瓶颈在上游靶点选择，现有数据距构建生物学因果模型差 1000 倍，未来竞争将聚焦数据、实验平台和人才结构等多层面。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=8660c7808d6ec6ee09c53cdafadd84152d6b978904c291c987ea43c7a30dbb9936dcdc418f8c&amp;idx=1&amp;mid=2649802403&amp;sn=254c02066da402300ef1b7538ef5207a#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="技术专家共探-ai-coding-应用关键问题" tabindex="-1"><a class="header-anchor" href="#技术专家共探-ai-coding-应用关键问题"><span>技术专家共探 AI Coding 应用关键问题</span></a></h3><p>多位技术专家探讨 AI Coding：AI 能赋能业务但不会减少人员，开发人员需担更多质量责任；MCP 等概念用于约束 Agent 输出；可从输入输出等多方面保障代码质量；要合理设置 Agent 权限，持续治理安全风险。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bc3a1ff42959de188d0a93f3a64d5b0b4611aa2135e7849f38f18c22e97dbc76bf0c91187337&amp;idx=2&amp;mid=2651290628&amp;sn=997449e01beb8b31ba43fa3fb760d5c9#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="百度hpd-parsing-文档解析速度暴涨3倍" tabindex="-1"><a class="header-anchor" href="#百度hpd-parsing-文档解析速度暴涨3倍"><span>百度HPD - Parsing：文档解析速度暴涨3倍</span></a></h3><p>百度PaddleOCR：推出HPD - Parsing模型，通过层级并行解码，将文档解析速度大幅提升。其训练方法巧妙，先找瓶颈再优化，利用任务结构并行性分阶段迁移，效率与精度双高。<a href="https://mp.weixin.qq.com/s?__biz=MzkzNjgwNzMwNQ==&amp;chksm=c3baab0a995d79482fb34e1a8fe6dbb88696bc51d20226c2c928f28ab50d5eb7865a0b3320be&amp;idx=1&amp;mid=2247489395&amp;sn=b15586541d2cda54f18e24f7787cadc6#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="evermind-让ai自进化从研究走向产品" tabindex="-1"><a class="header-anchor" href="#evermind-让ai自进化从研究走向产品"><span>EverMind：让AI自进化从研究走向产品</span></a></h3><p>EverMind：同一模型换 Harness 表现或不同，暴露自进化关键问题。用 HarnessBank、Raven、EverMe 解决，其 C 端产品 EverMe 上线内测，连接多环节，让自进化从论文走向用户可感知。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85d48a58fdd60821575f0089d8b30da4bdbdea502fa939e2a21af3993837eba8fff3d78712de&amp;idx=1&amp;mid=2651049640&amp;sn=aab578d02717eca8babf75556823c07c#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="唐皓凝-构建通用可重构光子平台" tabindex="-1"><a class="header-anchor" href="#唐皓凝-构建通用可重构光子平台"><span>唐皓凝：构建通用可重构光子平台</span></a></h3><p>MIT唐皓凝：从机械自由度入手构建可重构光子平台，将其视为基础研究平台。未来要发展可编程光子架构，挑战是把机械自由度变为可规模化控制变量，AI可扩大设计空间。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=863d25a06f8e756de55e21199a6c8789702e7f37eb9a00df58ba4e145bc14330eadbe24d2ada&amp;idx=2&amp;mid=2649802403&amp;sn=791d65d2b16da3fe84e064fcabc0d4c9#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="北大卢宗青-隐空间是具身智能之路" tabindex="-1"><a class="header-anchor" href="#北大卢宗青-隐空间是具身智能之路"><span>北大卢宗青：隐空间是具身智能之路</span></a></h3><p>北大卢宗青：人类视频是具身智能唯一可规模化数据路径；隐空间世界动作模型训练成本低、易学物理规律；具身确定性技术未现，2 - 3年有望商业落地，正迈向具身基础模型1.0时代。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=9141b834ab9ed1e8e54fd4b9abef88f10b53d72e21edf9ad4050919e4a31f942bba817c9a2d8&amp;idx=1&amp;mid=2247741425&amp;sn=9e3cf162fec88b968e232604b44b80d5#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="pi适配deepseek-缓存省成本官方将至" tabindex="-1"><a class="header-anchor" href="#pi适配deepseek-缓存省成本官方将至"><span>Pi适配DeepSeek，缓存省成本官方将至</span></a></h3><p>民间开源编程Agent「Pi」适配DeepSeek，使缓存不命中率低至0.03%，调用成本大幅降低。Composio测试，Pi完成任务平均成本最低。而DeepSeek正组建团队开发官方Harness。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9b21729951037f43307739fa9e60c7b4d3a6da01f3f5ba109de19721f9ff3680b348da23429&amp;idx=2&amp;mid=2247911229&amp;sn=7941667c94da8071fc981dc6c76d12b3#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="ai编程代理-一键克隆任意网站" tabindex="-1"><a class="header-anchor" href="#ai编程代理-一键克隆任意网站"><span>AI编程代理：一键克隆任意网站</span></a></h3><p>小G介绍的项目超厉害，给AI编程代理URL，就能克隆网站成Next.js应用。给出快速开始步骤，支持Claude Code等多平台，还说明了工作原理和常用命令。<a href="https://mp.weixin.qq.com/s?__biz=MzkxNjQ4MzMyOA==&amp;chksm=c0ecc18f1e4cc332610d9167319ffb676671e21977365bbfe6158f81f4b9f5f2f3f9f30fef0b&amp;idx=1&amp;mid=2247496007&amp;sn=3712c519da314bfa423be64d57f6d795#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude挑战黎曼猜想取得重大突破" tabindex="-1"><a class="header-anchor" href="#claude挑战黎曼猜想取得重大突破"><span>Claude挑战黎曼猜想取得重大突破</span></a></h3><p>Anthropic让Claude挑战黎曼猜想，虽未证明，但把零点在临界线上比例下界从41.6%提升到67.2%。多智能体自主协作，经严格验证，是AI数学里程碑。<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MTYzMzMxMA==&amp;chksm=c3a80f22e5f0983599d1bf6e6e90dc2d70acd71fe26b1131e77b57076341b159a5c0a7c179e2&amp;idx=2&amp;mid=2247509797&amp;sn=771c6647938996b28841ad7c1607f2ff#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="meta开源muse-glimmer-本地agent小钢炮来袭" tabindex="-1"><a class="header-anchor" href="#meta开源muse-glimmer-本地agent小钢炮来袭"><span>Meta开源Muse Glimmer，本地Agent小钢炮来袭</span></a></h3><p>Meta：开源Agent模型Muse Glimmer，30B参数能跑在本地设备，多项基准领先。它可完成多类任务、接受多模态输入，经优化速度快，开发者几分钟就能上手。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3Mzg5MjY3Nw==&amp;chksm=cfd3f9a4c2feaea93dd72babc3660b274090b97ce03cc2b89edae0edbcfe8a83eec788bb8a80&amp;idx=1&amp;mid=2247526681&amp;sn=e760f4a46cf4c4c863a6fa1161bc0062#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anydoc-14-种格式一键转-markdown" tabindex="-1"><a class="header-anchor" href="#anydoc-14-种格式一键转-markdown"><span>anydoc：14 种格式一键转 Markdown</span></a></h3><p>Firecrawl 团队：为满足企业文档转 Markdown 需求，开发 anydoc 库。它支持 14 种格式，输出一致，转换快，有浏览器版保隐私，提供多编程接口，值得一试。<a href="https://mp.weixin.qq.com/s?__biz=MzkwMjQ0NzI0OQ==&amp;chksm=c130910acebfb8d2ea24fc3edbbbeb3ce5780dd6130b672dab943246c07c94ef38bd71a4c5ed&amp;idx=1&amp;mid=2247506698&amp;sn=eecbe9b2ed6842240af10088dd4cd4eb#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="斯坦福skill原生llm提升长程任务能力" tabindex="-1"><a class="header-anchor" href="#斯坦福skill原生llm提升长程任务能力"><span>斯坦福Skill原生LLM提升长程任务能力</span></a></h3><p>普林斯顿、斯坦福等团队：提出Skill-Native大模型，用Skill Entropy度量技能切换难度，搭建评测工具，还将其作为训练信号，提升多模型跨技能长程任务准确率，且技能熵可复用。<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MTYzMzMxMA==&amp;chksm=c3ee54729b90608068390eb6dfaec41d897bf05645044fa6c1b7237099e71e135b878f88227a&amp;idx=1&amp;mid=2247509797&amp;sn=efdbac68042f181575db3c51e7f76084#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="西交大-qqworld-提升世界模型成功率" tabindex="-1"><a class="header-anchor" href="#西交大-qqworld-提升世界模型成功率"><span>西交大 QQWorld 提升世界模型成功率</span></a></h3><p>西安交通大学团队：针对 LeWorldModel 潜空间重尾问题，提出 QQWorld 用分位数匹配替换 EP 正则，在四环境中提升规划成功率，Cross - Batch QQ 为小批量训练提供可扩展方案。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=857ffab4c6b07dedb9ac32fc57a8e86647669e21cc3c7e0843002c4f74b1587fe8b03a9f8892&amp;idx=2&amp;mid=2651049617&amp;sn=5500d3dbcc92ac966f2c00278d2dbc33#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',47)]))}const s=a(i,[["render",c]]),t=JSON.parse('{"path":"/posts/2026-08-11.html","title":"AI日报：寻明生科获1亿美元融资，迈向生物世界模型; 黄仁勋：AI算力要成「可投资资产」; 黄仁勋拉金融巨鳄砸5000亿建AI工厂","lang":"zh-CN","frontmatter":{"date":"2026-08-11T00:00:00.000Z","title":"AI日报：寻明生科获1亿美元融资，迈向生物世界模型; 黄仁勋：AI算力要成「可投资资产」; 黄仁勋拉金融巨鳄砸5000亿建AI工厂"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"寻明生科获1亿美元融资，迈向生物世界模型","slug":"寻明生科获1亿美元融资-迈向生物世界模型","link":"#寻明生科获1亿美元融资-迈向生物世界模型","children":[]},{"level":3,"title":"黄仁勋：AI算力要成「可投资资产」","slug":"黄仁勋-ai算力要成「可投资资产」","link":"#黄仁勋-ai算力要成「可投资资产」","children":[]},{"level":3,"title":"黄仁勋拉金融巨鳄砸5000亿建AI工厂","slug":"黄仁勋拉金融巨鳄砸5000亿建ai工厂","link":"#黄仁勋拉金融巨鳄砸5000亿建ai工厂","children":[]},{"level":3,"title":"Claude全球推行文本隐形水印引争议","slug":"claude全球推行文本隐形水印引争议","link":"#claude全球推行文本隐形水印引争议","children":[]},{"level":3,"title":"华为天才少年创业做具身大脑","slug":"华为天才少年创业做具身大脑","link":"#华为天才少年创业做具身大脑","children":[]},{"level":3,"title":"Zig创始人批Bun AI重构代码是‘烂代码’","slug":"zig创始人批bun-ai重构代码是-烂代码","link":"#zig创始人批bun-ai重构代码是-烂代码","children":[]},{"level":3,"title":"Daphne Koller：AI制药缺1000倍数据","slug":"daphne-koller-ai制药缺1000倍数据","link":"#daphne-koller-ai制药缺1000倍数据","children":[]},{"level":3,"title":"技术专家共探 AI Coding 应用关键问题","slug":"技术专家共探-ai-coding-应用关键问题","link":"#技术专家共探-ai-coding-应用关键问题","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"百度HPD - Parsing：文档解析速度暴涨3倍","slug":"百度hpd-parsing-文档解析速度暴涨3倍","link":"#百度hpd-parsing-文档解析速度暴涨3倍","children":[]},{"level":3,"title":"EverMind：让AI自进化从研究走向产品","slug":"evermind-让ai自进化从研究走向产品","link":"#evermind-让ai自进化从研究走向产品","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"唐皓凝：构建通用可重构光子平台","slug":"唐皓凝-构建通用可重构光子平台","link":"#唐皓凝-构建通用可重构光子平台","children":[]},{"level":3,"title":"北大卢宗青：隐空间是具身智能之路","slug":"北大卢宗青-隐空间是具身智能之路","link":"#北大卢宗青-隐空间是具身智能之路","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"Pi适配DeepSeek，缓存省成本官方将至","slug":"pi适配deepseek-缓存省成本官方将至","link":"#pi适配deepseek-缓存省成本官方将至","children":[]},{"level":3,"title":"AI编程代理：一键克隆任意网站","slug":"ai编程代理-一键克隆任意网站","link":"#ai编程代理-一键克隆任意网站","children":[]},{"level":3,"title":"Claude挑战黎曼猜想取得重大突破","slug":"claude挑战黎曼猜想取得重大突破","link":"#claude挑战黎曼猜想取得重大突破","children":[]},{"level":3,"title":"Meta开源Muse Glimmer，本地Agent小钢炮来袭","slug":"meta开源muse-glimmer-本地agent小钢炮来袭","link":"#meta开源muse-glimmer-本地agent小钢炮来袭","children":[]},{"level":3,"title":"anydoc：14 种格式一键转 Markdown","slug":"anydoc-14-种格式一键转-markdown","link":"#anydoc-14-种格式一键转-markdown","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"斯坦福Skill原生LLM提升长程任务能力","slug":"斯坦福skill原生llm提升长程任务能力","link":"#斯坦福skill原生llm提升长程任务能力","children":[]},{"level":3,"title":"西交大 QQWorld 提升世界模型成功率","slug":"西交大-qqworld-提升世界模型成功率","link":"#西交大-qqworld-提升世界模型成功率","children":[]}]}],"git":{"updatedTime":1788510497000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"50110f95399977aa816da540afacbf29cc38efd0","time":1788510497000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-09-04T08:28:17.781Z"}]},"filePathRelative":"posts/2026-08-11.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-08-11 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>寻明生科获1亿美元融资，迈向生物世界模型</h3>\\n<p>寻明生科获1亿美元B轮融资，累计近2亿。将强化生物基座模型研发，升级实验体系。其闭环基础设施让模型持续进化，已产出高价值抗体，与药企合作，创始人称迈向生物世界模型。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzkwMDI2ODE0OQ==&amp;chksm=c1d288a585e580dcf9f41387611ae0bdaa13e1f8188385c3dafa9f942d60a70977a489aa7d0f&amp;idx=1&amp;mid=2247504143&amp;sn=10419b6dba000ac35a3602c5ca383468#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{s as comp,t as data};
